local KTool = CS.Engine.Lib.KTool
local UIModule          = CS.Engine.UI.UIModule
local MaidCoffeeGuestOptionController = Class('MaidCoffeeGuestOptionController')
local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")
local CellCount = 3
local SceneManagementIns        = SceneManagement:GetInstance()
local CellPath = "Game.MaidCoffee.MaidCoffeeGuestUIDialog.Cell.MaidCoffeeGuestOptionCell"
local CinemachineVirtualCamera = CS.Cinemachine.CinemachineVirtualCamera

function MaidCoffeeGuestOptionController:__init()
    self.optionEnv = {}
    self.isInDialog = false
    self.enterStoryCb = nil
    self._locationVirtualCamera = nil
end

function MaidCoffeeGuestOptionController:__delete()
    self.optionEnv = nil
    self.isInDialog = false
    self.enterStoryCb = nil
    self._locationVirtualCamera = nil
end

function MaidCoffeeGuestOptionController:Awake()
    self:InitNodeEnv()
    self:SetVirtualCamera(false)
    Events.Broadcast(MaidCoffeeConstants.EventNames.SetRoleControllerShowState,true)
    self.tipRefreshEvent = Events.AddListener(MaidCoffeeConstants.EventNames.MaidCoffeeRefreshNearTip,Bind(self,self.OnRefreshTipShow))
end

function MaidCoffeeGuestOptionController:SetEnterStoryCallBack(cb)
    self.enterStoryCb = cb
end

--[[function MaidCoffeeGuestOptionController:InitSceneInstance()
    ---@type SceneInstance
    local sceneInstance = SceneManagementIns:GetSceneInstance(Constants.IdSceneSetting46)
    self._sceneInstance = sceneInstance
end]]

function MaidCoffeeGuestOptionController:InitNodeEnv()
    for i = 1, CellCount do
        local node = self["OptionNode"..i]
        if node then
            local env = CfUtils.GetLuaScr(node,CellPath)
            if not isNull(env) then
                env:SetClickCallBack(Bind(self,self.OnOptionCellClick))
                table.insert(self.optionEnv,env)
            end
        end
    end
end

function MaidCoffeeGuestOptionController:OnOptionCellClick(data)
    KTool.SetActive(self.controller.gameObject,false)
    ---禁用掉输入和隐藏摇杆
    Events.Broadcast(MaidCoffeeConstants.EventNames.SetRoleControllerShowState,false)
    --- 隐藏 WorldSpaceCanvas:
    Events.Broadcast(MaidCoffeeConstants.EventNames.ShowWorldSpaceCanvas,false)
    if data.type == MaidCoffeeConstants.OptionType.Guest  then
        local tempData = data.data.eventData
        self.isInDialog = true
        self:SetVirtualCamera(true,data.type,tempData.eventId)
        self:StartTalking(tempData)
    elseif data.type == MaidCoffeeConstants.OptionType.Business then
        self:SetVirtualCamera(true,data.type)
        local MaidCoffeeUtils     = import("Game.MaidCoffee.MaidCoffeeUtils")
        if not isNull(self.enterStoryCb) then
            self.enterStoryCb()
        end
        MaidCoffeeUtils.OpenBusinessStory()
    end
end

function MaidCoffeeGuestOptionController:SetVirtualCamera(status,type,eventId)
    Events.Broadcast(MaidCoffeeConstants.EventNames.MaidCoffeeFreshLocationCam,status,type,eventId)
end

function MaidCoffeeGuestOptionController:StartTalking(data)
    UIModule.OpenDialog({ id = Constants.UITypeIds.MaidCoffeeGuestTalkingDialog, parameters = { data = data, callBack = Bind(self,self.OnDialogEnd) } },{{id = Constants.UITypeIds.UIMaidCoffeeMainDialog}})
end

function MaidCoffeeGuestOptionController:OnDialogEnd(data)
    self.isInDialog = false
end

function MaidCoffeeGuestOptionController:OnRefreshTipShow(data)
    if self.isInDialog then return end
    KTool.SetActive(self.controller.gameObject,true)
    for i, v in pairs(self.optionEnv) do
        local tempData = data[i]
        if not isNull(tempData) then
            KTool.SetActive(v.controller.gameObject,true)
            v:RefreshShow(tempData)
        else
            KTool.SetActive(v.controller.gameObject,false)
        end
    end
end

function MaidCoffeeGuestOptionController:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    if not isNull(self.tipRefreshEvent) then
        Events.RemoveListener(MaidCoffeeConstants.EventNames.MaidCoffeeRefreshNearTip,self.tipRefreshEvent)
    end
end

return MaidCoffeeGuestOptionController